package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.XmlDeclaration;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class XmlDeclaration_getWholeDeclaration_TriageGen0Test {

    @Test
    public void testGetWholeDeclaration_NullName() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration(null, null, false);
        assertEquals("", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_NameIsEmpty() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("", null, false);
        assertEquals("", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_NameIsXml() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        assertEquals("xml", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_NameIsXml_VersionPresent() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        xmlDeclaration.attributes.put("version", "1.0");
        assertEquals("xml version=\"1.0\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_NameIsXml_VersionEncodingPresent() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        xmlDeclaration.attributes.put("version", "1.0");
        xmlDeclaration.attributes.put("encoding", "UTF-8");
        assertEquals("xml version=\"1.0\" encoding=\"UTF-8\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_NameIsXml_VersionEncodingNotPresent() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        xmlDeclaration.attributes.put("version", "1.0");
        assertEquals("xml version=\"1.0\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_NameIsXml_EncodingPresent() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        xmlDeclaration.attributes.put("encoding", "UTF-8");
        assertEquals("xml encoding=\"UTF-8\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_NameIsXml_VersionEncodingPresentButNameIsNotXml() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("tag", null, false);
        xmlDeclaration.attributes.put("version", "1.0");
        xmlDeclaration.attributes.put("encoding", "UTF-8");
        assertEquals("tag", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_NameIsXml_VersionEncodingAttributesSizeIsOne() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        xmlDeclaration.attributes.put("version", "1.0");
        assertEquals("xml", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_NameIsXml_VersionEncodingAttributesSizeIsMoreThanOne() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        xmlDeclaration.attributes.put("version", "1.0");
        xmlDeclaration.attributes.put("encoding", "UTF-8");
        xmlDeclaration.attributes.put("other", "value");
        assertEquals("xml version=\"1.0\" encoding=\"UTF-8\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_NameIsXml_VersionEncodingAttributesSizeIsZero() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        assertEquals("xml", xmlDeclaration.getWholeDeclaration());
    }
}
